parameters.jsCode:
const raw = $input.first().json;
const rawBody = raw.body || raw;
const payload = rawBody.data || rawBody;

const fullName = payload.fullName || payload.candidateName || 'Thành Viên Mới';
const jobTitle = payload.jobTitle || 'Chuyên viên Kỹ thuật';
const department = payload.departmentName || payload.department || 'Phòng Phát Triển Công Nghệ Số';
const email = payload.email || payload.candidateEmail || 'quocthangngo2006@gmail.com';
const tempPassword = payload.tempPassword || 'Enterprise@2026#';
const portalUrl = payload.portalUrl || 'https://levitra-them-utah-fonts.trycloudflare.com/login';
const fromEmail = payload.fromEmail || 'quocthangngo2006@gmail.com';
const userId = payload.userId || 1;

const htmlTemplate = `
<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <style>
    body { font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif; background-color: #f1f5f9; margin: 0; padding: 20px; }
    .container { max-width: 620px; margin: 0 auto; background: #ffffff; border-radius: 12px; overflow: hidden; box-shadow: 0 4px 15px rgba(0,0,0,0.08); }
    .header { background: linear-gradient(135deg, #059669 0%, #10b981 100%); color: #ffffff; padding: 35px 20px; text-align: center; }
    .header h1 { margin: 0; font-size: 24px; font-weight: 700; letter-spacing: 0.5px; }
    .content { padding: 30px; color: #334155; line-height: 1.6; }
    .card { background: #f8fafc; border: 1px solid #e2e8f0; border-radius: 8px; padding: 20px; margin: 20px 0; }
    .card-title { font-weight: 700; color: #0f172a; margin-bottom: 12px; font-size: 16px; border-bottom: 2px solid #10b981; padding-bottom: 6px; display: inline-block; }
    .cred-box { background: #eff6ff; border: 1px solid #bfdbfe; border-radius: 8px; padding: 18px; margin: 20px 0; }
    .cred-title { font-weight: 700; color: #1e40af; margin-bottom: 10px; font-size: 15px; }
    .item { margin: 8px 0; font-size: 15px; }
    .code-tag { background: #dbeafe; color: #1e3a8a; padding: 4px 10px; border-radius: 6px; font-family: monospace; font-size: 16px; font-weight: bold; letter-spacing: 1px; }
    .btn { display: inline-block; background: #059669; color: #ffffff !important; padding: 14px 28px; text-decoration: none; border-radius: 8px; font-weight: 600; text-align: center; margin: 15px 0; }
    .kit-box { background: #ecfdf5; border: 1px solid #a7f3d0; border-radius: 8px; padding: 15px; margin-top: 15px; color: #065f46; font-size: 14px; }
    .footer { text-align: center; font-size: 13px; color: #94a3b8; padding: 20px; border-top: 1px solid #e2e8f0; }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      <h1>CHÀO MỪNG GIA NHẬP ĐỘI NGŨ</h1>
      <p style="margin: 6px 0 0 0; opacity: 0.95; font-size: 15px;">Enterprise Multi-Agent HR Ecosystem</p>
    </div>
    <div class="content">
      <p>Thân gửi <strong>${fullName}</strong>,</p>
      <p>Ban Giám đốc cùng toàn thể đại gia đình công ty xin gửi lời chúc mừng nồng nhiệt nhất tới bạn! Chúng tôi vô cùng vui mừng khi bạn chính thức gia nhập đội ngũ.</p>

      <div class="card">
        <div class="card-title">📌 THÔNG TIN VỊ TRÍ CÔNG TÁC</div>
        <div class="item"><strong>Chức danh:</strong> ${jobTitle}</div>
        <div class="item"><strong>Phòng ban:</strong> ${department}</div>
        <div class="item"><strong>Chế độ đãi ngộ:</strong> 100% Bảo hiểm BHXH/BHYT + Gói khám sức khỏe định kỳ + Trợ cấp thiết bị & đào tạo</div>
      </div>

      <div class="cred-box">
        <div class="cred-title">🔐 TÀI KHOẢN TRUY CẬP HỆ THỐNG NỘI BỘ (HR PORTAL)</div>
        <div class="item">👤 <strong>Tên đăng nhập (Email):</strong> <code>${email}</code></div>
        <div class="item">🔑 <strong>Mật khẩu tạm thời:</strong> <span class="code-tag">${tempPassword}</span></div>
        <div class="item">🌐 <strong>Cổng thông tin nhân sự:</strong> <a href="${portalUrl}">${portalUrl}</a></div>
        <p style="font-size: 13px; color: #64748b; margin: 10px 0 0 0;"><i>* Lưu ý an toàn: Vui lòng đổi mật khẩu mới ngay trong lần đầu tiên đăng nhập hệ thống.</i></p>
      </div>

      <div class="kit-box">
        🎁 <strong>Gói Chào Mừng (Welcome Kit) chuẩn bị cho bạn vào Ngày 1 Onboarding:</strong>
        <ul style="margin: 6px 0 0 0; padding-left: 20px;">
          <li>Laptop làm việc cấu hình cao & thẻ nhân viên.</li>
          <li>Bộ quà tặng chào mừng (Áo polo, sổ tay văn hóa doanh nghiệp).</li>
          <li>Lộ trình hội nhập 30 ngày (Onboarding Journey) và Buddy hỗ trợ 1-kèm-1.</li>
        </ul>
      </div>

      <div style="text-align: center; margin: 25px 0;">
        <a href="${portalUrl}" class="btn" target="_blank">🚀 Kích Hoạt & Đăng Nhập Hệ Thống</a>
      </div>

      <p>Chúc bạn sẽ có một hành trình phát triển vượt bậc và gặt hái nhiều thành công rực rỡ cùng chúng tôi!</p>
      <p>Trân trọng,<br><strong>Phòng Nhân Sự & Văn Hóa Doanh Nghiệp</strong></p>
    </div>
    <div class="footer">
      © 2026 Enterprise Corporation. Email này được tạo và gửi tự động bởi n8n Workflow Automation.
    </div>
  </div>
</body>
</html>
`;

return [{
  json: {
    fromEmail,
    userId,
    fullName,
    jobTitle,
    department,
    email,
    tempPassword,
    portalUrl,
    telegramChatId: payload.telegramChatId || payload.chatId || '8928574834',
    emailSubject: `[Welcome Kit] Chúc mừng ${fullName} chính thức gia nhập ${department} - Vị trí ${jobTitle}! 🎉`,
    emailHtml: htmlTemplate,
    telegramAlert: `🎉 <b>NHÂN SỰ MỚI GIA NHẬP DOANH NGHIỆP</b>\n• Họ tên: <b>${fullName}</b> (ID #${userId})\n• Vị trí: <b>${jobTitle}</b>\n• Phòng ban: <b>${department}</b>\n• Email: <code>${email}</code>\n\n⚡ <i>IT Helpdesk & HR Operations vui lòng chuẩn bị Welcome Kit, Laptop và bàn làm việc trước ngày Onboarding!</i>`
  }
}];

parameters.query:
={{ (() => {
  const info = $('3. Soạn nội dung Thư chúc mừng & Tài khoản').first().json;
  const targetEmail = info.email || 'unknown@company.com';
  const details = JSON.stringify({
    userId: info.userId,
    fullName: info.fullName,
    jobTitle: info.jobTitle,
    department: info.department
  }).replace(/'/g, "\\'");
  return "INSERT INTO audit_logs (action, actor_ip, target_email, details, created_at) VALUES ('EMPLOYEE_HIRED_PROVISIONED', '127.0.0.1', '" + targetEmail + "', '" + details + "', NOW());";
})() }}
